add(23,'hypothesis testing',r'''Without loss of generality, we assume $\varepsilon_i\overset{i.i.d.}{\sim}N(0,\sigma^2)$ with $0\le\sigma^2<1$, $\mathcal A_i\overset{i.i.d.}{\sim}N(0,1)$ and $\|\mathcal X^*\|_{\mathrm F}+\sigma^2=1$ in establishing the computational lower bound for scalar-on-tensor regression (10) (see Supplement G.1 for a proof). We also consider the setting $p_1=\cdots=p_d=p$ and $r_1^*=\cdots=r_d^*=r^*$ throughout this section.
We consider a canonical hypothesis testing formulation of scalar-on-tensor regression:
\[
H_0:\{(y_i,\operatorname{vec}(\mathcal A_i))\}_{i=1}^n\overset{i.i.d.}{\sim}N(0,\mathbf I_{1+p^d}),
\]
\[
H_1:\{(y_i,\operatorname{vec}(\mathcal A_i))\}_{i=1}^n:\mathcal X^*=\sqrt{1-\sigma^2}\mathbf x^{*\otimes d},
\]
\[
\mathbf x^*=(x_1^*,\ldots,x_p^*),\ x_j^*\overset{i.i.d.}{\sim}\operatorname{Uniform}(\{p^{-1/2},-p^{-1/2}\});
\]
\[
\text{for }i\in[n],\mathcal A_i\overset{i.i.d.}{\sim}N(0,1),y_i\text{ is i.i.d. generated}
\]
\[
\text{via }y_i=\langle\mathcal X^*,\mathcal A_i\rangle+\varepsilon_i,\ \varepsilon_i\overset{i.i.d.}{\sim}N(0,\sigma^2).
\]
(14)''',[17],[],[r'H_0',r'H_1',r'\sqrt{1-\sigma^2}\mathbf x^{*\otimes d}'],'Complete main-text null and planted symmetric rank-one alternative for low-degree testing. Covariate variance1 is distinct from Definition2 variance1/n. A common sampled signal couples observations under H1; iid is naturally conditional on this signal. Preserve the unsquared norm in the preceding normalization, which conflicts with the displayed square-root amplitude.','Section 5 — Hypothesis test (14)',kind='source_passage')
add(24,'initialization',r'''the initialization $\mathcal X^0$ satisfies $\|\mathcal X^0-\mathcal X^*\|_{\mathrm F}\le\frac{R_{2\mathbf r}}{(d+m)(1+R_{2\mathbf r+\mathbf r^*}-R_{2\mathbf r})}\lambda$''',[10],[12,13],[r'\frac{R_{2\mathbf r}}{(d+m)(1+R_{2\mathbf r+\mathbf r^*}-R_{2\mathbf r})}\lambda'],'Exact RGD initialization-distance condition from Theorem1. Theorems5,6,8 promise this condition; it is an output property, not an additional assumed initialization. RGD’s separate TRIP upper/signal lower conditions are archived as auxiliary context.','Theorem 1 — Initialization condition',kind='theorem_excerpt')
add(25,'initialization',r'''the initialization $\mathcal X^0$ satisfies $\|\mathcal X^0-\mathcal X^*\|_{\mathrm F}\le\frac{1-R_{2\mathbf r}}{4(d+m)(\sqrt{d+m}+1)(1+R_{2\mathbf r+\mathbf r^*}-R_{2\mathbf r})}\lambda$''',[11],[12,13],[r'\frac{1-R_{2\mathbf r}}{4(d+m)(\sqrt{d+m}+1)(1+R_{2\mathbf r+\mathbf r^*}-R_{2\mathbf r})}\lambda'],'Exact RGN initialization-distance condition from Theorem2, distinct from Theorem1’s threshold. Theorems5,6,8 guarantee it; do not transfer RGD-specific additional assumptions into Theorem2.','Theorem 2 — Initialization condition',kind='theorem_excerpt')
